def check_solutions(limit):
    solutions = []
    for n in range(26, limit):
        val = n**2 - 625
        if val > 0:
            # Check if val is of the form 2^a * 5^b
            temp_val = val
            a = 0
            while temp_val > 0 and temp_val % 2 == 0:
                temp_val //= 2
                a += 1

            b = 0
            while temp_val > 0 and temp_val % 5 == 0:
                temp_val //= 5
                b += 1

            if temp_val == 1:
                solutions.append((a, b, n))
    return solutions

print(check_solutions(10000))
